    SET
        status = 'VALIDATION_FAILED',
        message = v_validation_error
    WHERE
        cleanup_id = '2696b172-7af5-4065-bdbc-9414f4cf33eb'
        AND charge_id = 1247361;
   
    RETURN;
END IF;

END IF;

